    CatalogEntry(category='EmotionalSupport', category_group='emotional_reflection', variant_id='topic_emotionalsupport_8ee9fda8bde4.care_1', semantic_group='emotional_reflection.topic_emotionalsupport_8ee9fda8bde4', output_mode='self_talk', trigger='idle', required_context='none', tone='gentle_cautious', interrupt_cost=0, cooldown_hours=120.0, semantic_cooldown_hours=72.0, max_per_day=1, weight=1.0, text='压力装得太满时，暂停并不是退缩，只是在给系统留余量。', source_kind='topic_rewrite', source_reference='legacy:62545;topic:topic_emotionalsupport_8ee9fda8bde4', rewrite_reason='rewritten as cautious general care without claiming user state'),
