    CatalogEntry(category='EmotionalSupport', category_group='emotional_reflection', variant_id='topic_emotionalsupport_c63fcc64f3e7.care_2', semantic_group='emotional_reflection.topic_emotionalsupport_c63fcc64f3e7', output_mode='self_talk', trigger='idle', required_context='none', tone='gentle_cautious', interrupt_cost=0, cooldown_hours=120.0, semantic_cooldown_hours=72.0, max_per_day=1, weight=1.0, text='有些难受无需马上解释清楚，先让感受有地方安静落下。', source_kind='topic_rewrite', source_reference='legacy:62520;topic:topic_emotionalsupport_c63fcc64f3e7', rewrite_reason='rewritten as cautious general care without claiming user state'),
