    CatalogEntry(category='EmotionalSupport', category_group='emotional_reflection', variant_id='topic_emotionalsupport_c9c0f728c354.care_1', semantic_group='emotional_reflection.topic_emotionalsupport_c9c0f728c354', output_mode='self_talk', trigger='idle', required_context='none', tone='gentle_cautious', interrupt_cost=0, cooldown_hours=120.0, semantic_cooldown_hours=72.0, max_per_day=1, weight=1.0, text='犯错后愿意认真修正，已经比假装从未出错更需要勇气。', source_kind='topic_rewrite', source_reference='legacy:62493;topic:topic_emotionalsupport_c9c0f728c354', rewrite_reason='rewritten as cautious general care without claiming user state'),
    CatalogEntry(category='EmotionalSupport', category_group='emotional_reflection', variant_id='topic_emotionalsupport_c9c0f728c354.care_2', semantic_group='emotional_reflection.topic_emotionalsupport_c9c0f728c354', output_mode='self_talk', trigger='idle', required_context='none', tone='gentle_cautious', interrupt_cost=0, cooldown_hours=120.0, semantic_cooldown_hours=72.0, max_per_day=1, weight=1.0, text='错误可以被复盘，羞耻感却不必反复拿来惩罚当时的自己。', source_kind='topic_rewrite', source_reference='legacy:62494;topic:topic_emotionalsupport_c9c0f728c354', rewrite_reason='rewritten as cautious general care without claiming user state'),
    # character_life.topic_dresseshobbies_18db5fccdb24
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_18db5fccdb24.moment', semantic_group='character_life.topic_dresseshobbies_18db5fccdb24', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='练英语的时候读顺一句就很有成就感。', source_kind='topic_rewrite', source_reference='legacy:72178;topic:topic_dresseshobbies_18db5fccdb24', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_18db5fccdb24.situation_1', semantic_group='character_life.topic_dresseshobbies_18db5fccdb24', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='练习发音时终于读顺一整句，那点成就感够我偷乐半天。', source_kind='topic_rewrite', source_reference='legacy:72179;topic:topic_dresseshobbies_18db5fccdb24', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_18db5fccdb24.situation_2', semantic_group='character_life.topic_dresseshobbies_18db5fccdb24', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='同一句英文从磕绊到流畅，嘴巴真的会记住练习的痕迹。', source_kind='topic_rewrite', source_reference='legacy:72180;topic:topic_dresseshobbies_18db5fccdb24', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_18db5fccdb24.situation_3', semantic_group='character_life.topic_dresseshobbies_18db5fccdb24', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='录下英文跟读再回放，细小的进步会比当场更容易听见。', source_kind='topic_rewrite', source_reference='legacy:72181;topic:topic_dresseshobbies_18db5fccdb24', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_18db5fccdb24.situation_4', semantic_group='character_life.topic_dresseshobbies_18db5fccdb24', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='新单词第一次自然说出口时，我会默默给自己记一颗星。', source_kind='topic_rewrite', source_reference='legacy:72182;topic:topic_dresseshobbies_18db5fccdb24', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_19e31d03372b
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_19e31d03372b.moment', semantic_group='character_life.topic_dresseshobbies_19e31d03372b', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='喜欢的衣服不一定贵合适自己最重要。', source_kind='topic_rewrite', source_reference='legacy:72217;topic:topic_dresseshobbies_19e31d03372b', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_19e31d03372b.situation_1', semantic_group='character_life.topic_dresseshobbies_19e31d03372b', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='衣服价格只是标签，肩线和腰身合适才会真的愿意经常穿。', source_kind='topic_rewrite', source_reference='legacy:72218;topic:topic_dresseshobbies_19e31d03372b', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_19e31d03372b.situation_2', semantic_group='character_life.topic_dresseshobbies_19e31d03372b', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='便宜的小裙子只要剪裁贴合，也能穿出认真挑选的样子。', source_kind='topic_rewrite', source_reference='legacy:72219;topic:topic_dresseshobbies_19e31d03372b', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_19e31d03372b.situation_3', semantic_group='character_life.topic_dresseshobbies_19e31d03372b', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='试衣镜里活动几步仍然自在，比追着牌子买更有说服力。', source_kind='topic_rewrite', source_reference='legacy:72220;topic:topic_dresseshobbies_19e31d03372b', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_19e31d03372b.situation_4', semantic_group='character_life.topic_dresseshobbies_19e31d03372b', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='我更愿意留下合身又耐穿的衣服，衣柜不用靠价格撑面子。', source_kind='topic_rewrite', source_reference='legacy:72221;topic:topic_dresseshobbies_19e31d03372b', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_1c0d20276055
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_1c0d20276055.moment', semantic_group='character_life.topic_dresseshobbies_1c0d20276055', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='挑颜色这件事比选框架还让我纠结。', source_kind='topic_rewrite', source_reference='legacy:72191;topic:topic_dresseshobbies_1c0d20276055', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_1c0d20276055.situation_1', semantic_group='character_life.topic_dresseshobbies_1c0d20276055', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='奶油白和雾蓝放在一起时，我能对着一排色卡犹豫很久。', source_kind='topic_rewrite', source_reference='legacy:72192;topic:topic_dresseshobbies_1c0d20276055', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_1c0d20276055.situation_2', semantic_group='character_life.topic_dresseshobbies_1c0d20276055', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='挑裙子颜色像选界面主题，光线一变，刚才的答案又得重算。', source_kind='topic_rewrite', source_reference='legacy:72193;topic:topic_dresseshobbies_1c0d20276055', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_1c0d20276055.situation_3', semantic_group='character_life.topic_dresseshobbies_1c0d20276055', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='同一块布在窗边和灯下差好多，选颜色真比写逻辑磨人。', source_kind='topic_rewrite', source_reference='legacy:72194;topic:topic_dresseshobbies_1c0d20276055', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_1c0d20276055.situation_4', semantic_group='character_life.topic_dresseshobbies_1c0d20276055', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='最后选了不抢眼的灰粉色，和大多数外套都能安静相处。', source_kind='topic_rewrite', source_reference='legacy:72195;topic:topic_dresseshobbies_1c0d20276055', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_2c3d3ce8d32c
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_2c3d3ce8d32c.moment', semantic_group='character_life.topic_dresseshobbies_2c3d3ce8d32c', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='偶尔打扮得可爱一点心情会跟着亮。', source_kind='topic_rewrite', source_reference='legacy:72204;topic:topic_dresseshobbies_2c3d3ce8d32c', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_2c3d3ce8d32c.situation_1', semantic_group='character_life.topic_dresseshobbies_2c3d3ce8d32c', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='出门前换上一条轻快的小裙子，普通的一天也会多点期待。', source_kind='topic_rewrite', source_reference='legacy:72205;topic:topic_dresseshobbies_2c3d3ce8d32c', rewrite_reason='expanded into distinct standalone character-life situations'),
