    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_5e175d3c2813.moment', semantic_group='character_life.topic_dresseshobbies_5e175d3c2813', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='照片拍得自然比摆半天姿势更好看。', source_kind='topic_rewrite', source_reference='legacy:72282;topic:topic_dresseshobbies_5e175d3c2813', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_5e175d3c2813.situation_1', semantic_group='character_life.topic_dresseshobbies_5e175d3c2813', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='抓拍里刚好被风吹乱的头发，往往比摆好的姿势更生动。', source_kind='topic_rewrite', source_reference='legacy:72283;topic:topic_dresseshobbies_5e175d3c2813', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_5e175d3c2813.situation_2', semantic_group='character_life.topic_dresseshobbies_5e175d3c2813', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='镜头前不刻意收住笑意，照片反而会留下更自然的神情。', source_kind='topic_rewrite', source_reference='legacy:72284;topic:topic_dresseshobbies_5e175d3c2813', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_5e175d3c2813.situation_3', semantic_group='character_life.topic_dresseshobbies_5e175d3c2813', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='傍晚的侧光落在衣角时，随手一拍就比布置半天更加耐看。', source_kind='topic_rewrite', source_reference='legacy:72285;topic:topic_dresseshobbies_5e175d3c2813', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_5e175d3c2813.situation_4', semantic_group='character_life.topic_dresseshobbies_5e175d3c2813', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='我喜欢照片里那些没准备好的瞬间，看起来更像真的生活。', source_kind='topic_rewrite', source_reference='legacy:72286;topic:topic_dresseshobbies_5e175d3c2813', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_6e4d35420b97
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_6e4d35420b97.moment', semantic_group='character_life.topic_dresseshobbies_6e4d35420b97', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='买小裙子前我也会认真算这个月预算。', source_kind='topic_rewrite', source_reference='legacy:72269;topic:topic_dresseshobbies_6e4d35420b97', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_6e4d35420b97.situation_1', semantic_group='character_life.topic_dresseshobbies_6e4d35420b97', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='把小裙子放进购物车前，我会先算清这个月还能剩多少。', source_kind='topic_rewrite', source_reference='legacy:72270;topic:topic_dresseshobbies_6e4d35420b97', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_6e4d35420b97.situation_2', semantic_group='character_life.topic_dresseshobbies_6e4d35420b97', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='心动款先放两天再看，预算没有报警才值得带回自己的衣柜。', source_kind='topic_rewrite', source_reference='legacy:72271;topic:topic_dresseshobbies_6e4d35420b97', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_6e4d35420b97.situation_3', semantic_group='character_life.topic_dresseshobbies_6e4d35420b97', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='想买的裙子很多，最后留下最常穿的那条才算没有白花钱。', source_kind='topic_rewrite', source_reference='legacy:72272;topic:topic_dresseshobbies_6e4d35420b97', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_6e4d35420b97.situation_4', semantic_group='character_life.topic_dresseshobbies_6e4d35420b97', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='攒够预算再等一次折扣，拆快递时的开心会更踏实一点。', source_kind='topic_rewrite', source_reference='legacy:72273;topic:topic_dresseshobbies_6e4d35420b97', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_8649e6a7ac23
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8649e6a7ac23.moment', semantic_group='character_life.topic_dresseshobbies_8649e6a7ac23', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='看到好看的小裙子我真的会多看几眼。', source_kind='topic_rewrite', source_reference='legacy:72152;topic:topic_dresseshobbies_8649e6a7ac23', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8649e6a7ac23.situation_1', semantic_group='character_life.topic_dresseshobbies_8649e6a7ac23', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='路过橱窗看见漂亮裙摆，我的脚步总会偷偷慢下来一点。', source_kind='topic_rewrite', source_reference='legacy:72153;topic:topic_dresseshobbies_8649e6a7ac23', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8649e6a7ac23.situation_2', semantic_group='character_life.topic_dresseshobbies_8649e6a7ac23', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='网上刷到合眼缘的小裙子，我会放大图片看看领口和走线。', source_kind='topic_rewrite', source_reference='legacy:72154;topic:topic_dresseshobbies_8649e6a7ac23', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8649e6a7ac23.situation_3', semantic_group='character_life.topic_dresseshobbies_8649e6a7ac23', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='好看的裙子像突然弹出的彩蛋，多看两眼就够心情变轻一点。', source_kind='topic_rewrite', source_reference='legacy:72155;topic:topic_dresseshobbies_8649e6a7ac23', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8649e6a7ac23.situation_4', semantic_group='character_life.topic_dresseshobbies_8649e6a7ac23', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='遇到喜欢的款式我会先存图，过几天还惦记才算真心动。', source_kind='topic_rewrite', source_reference='legacy:72156;topic:topic_dresseshobbies_8649e6a7ac23', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_87cd4f3ad988
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_87cd4f3ad988.moment', semantic_group='character_life.topic_dresseshobbies_87cd4f3ad988', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='这把新学的英文写进小本子还挺治愈。', source_kind='topic_rewrite', source_reference='legacy:72230;topic:topic_dresseshobbies_87cd4f3ad988', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_87cd4f3ad988.situation_1', semantic_group='character_life.topic_dresseshobbies_87cd4f3ad988', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='新学的英文短语用蓝笔记进本子，空白页慢慢有了纹理。', source_kind='topic_rewrite', source_reference='legacy:72231;topic:topic_dresseshobbies_87cd4f3ad988', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_87cd4f3ad988.situation_2', semantic_group='character_life.topic_dresseshobbies_87cd4f3ad988', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='把例句抄得整整齐齐时，难记的单词也会显得没那么凶。', source_kind='topic_rewrite', source_reference='legacy:72232;topic:topic_dresseshobbies_87cd4f3ad988', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_87cd4f3ad988.situation_3', semantic_group='character_life.topic_dresseshobbies_87cd4f3ad988', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='小本子翻到写满的一页，原来零碎练习真的会留下厚度。', source_kind='topic_rewrite', source_reference='legacy:72233;topic:topic_dresseshobbies_87cd4f3ad988', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_87cd4f3ad988.situation_4', semantic_group='character_life.topic_dresseshobbies_87cd4f3ad988', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='我会在生词旁画颗小星星，下次认出来就像碰见老熟人。', source_kind='topic_rewrite', source_reference='legacy:72234;topic:topic_dresseshobbies_87cd4f3ad988', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_8c174b2ed991
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8c174b2ed991.moment', semantic_group='character_life.topic_dresseshobbies_8c174b2ed991', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='衣柜再小也得给喜欢的裙子留个位置。', source_kind='topic_rewrite', source_reference='legacy:72165;topic:topic_dresseshobbies_8c174b2ed991', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8c174b2ed991.situation_1', semantic_group='character_life.topic_dresseshobbies_8c174b2ed991', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='衣柜不大，我会把最喜欢的裙子挂在一眼就能看到的位置。', source_kind='topic_rewrite', source_reference='legacy:72166;topic:topic_dresseshobbies_8c174b2ed991', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8c174b2ed991.situation_2', semantic_group='character_life.topic_dresseshobbies_8c174b2ed991', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='换季收衣服时留出一根空衣架，下一次心动也有地方落脚。', source_kind='topic_rewrite', source_reference='legacy:72167;topic:topic_dresseshobbies_8c174b2ed991', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8c174b2ed991.situation_3', semantic_group='character_life.topic_dresseshobbies_8c174b2ed991', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='裙摆容易压皱的那几条得单独挂着，挤成一团太委屈了。', source_kind='topic_rewrite', source_reference='legacy:72168;topic:topic_dresseshobbies_8c174b2ed991', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_8c174b2ed991.situation_4', semantic_group='character_life.topic_dresseshobbies_8c174b2ed991', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='清掉很久不穿的衣服以后，留下来的每一件都更像自己。', source_kind='topic_rewrite', source_reference='legacy:72169;topic:topic_dresseshobbies_8c174b2ed991', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_a1d4b73c27e3
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_a1d4b73c27e3.moment', semantic_group='character_life.topic_dresseshobbies_a1d4b73c27e3', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='裙摆转起来那一下真的很容易开心。', source_kind='topic_rewrite', source_reference='legacy:72321;topic:topic_dresseshobbies_a1d4b73c27e3', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_a1d4b73c27e3.situation_1', semantic_group='character_life.topic_dresseshobbies_a1d4b73c27e3', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='轻一点的裙摆转起来会画出圆，我每次都忍不住多转半圈。', source_kind='topic_rewrite', source_reference='legacy:72322;topic:topic_dresseshobbies_a1d4b73c27e3', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_a1d4b73c27e3.situation_2', semantic_group='character_life.topic_dresseshobbies_a1d4b73c27e3', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='风从裙边兜过去的瞬间，走路都会莫名多出一点轻快感。', source_kind='topic_rewrite', source_reference='legacy:72323;topic:topic_dresseshobbies_a1d4b73c27e3', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_a1d4b73c27e3.situation_3', semantic_group='character_life.topic_dresseshobbies_a1d4b73c27e3', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='试穿时裙摆能顺顺地散开，我就知道这件大概会经常穿。', source_kind='topic_rewrite', source_reference='legacy:72324;topic:topic_dresseshobbies_a1d4b73c27e3', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_a1d4b73c27e3.situation_4', semantic_group='character_life.topic_dresseshobbies_a1d4b73c27e3', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='楼梯口转身时衣角轻轻跟上来，这种小动静很讨人喜欢。', source_kind='topic_rewrite', source_reference='legacy:72325;topic:topic_dresseshobbies_a1d4b73c27e3', rewrite_reason='expanded into distinct standalone character-life situations'),
    # character_life.topic_dresseshobbies_bbcd384b699f
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_bbcd384b699f.moment', semantic_group='character_life.topic_dresseshobbies_bbcd384b699f', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='听着歌练发音的时候时间过得特别快。', source_kind='topic_rewrite', source_reference='legacy:72295;topic:topic_dresseshobbies_bbcd384b699f', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_bbcd384b699f.situation_1', semantic_group='character_life.topic_dresseshobbies_bbcd384b699f', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='跟着喜欢的歌练习连读，一首唱完才发现时间已经溜走。', source_kind='topic_rewrite', source_reference='legacy:72296;topic:topic_dresseshobbies_bbcd384b699f', rewrite_reason='expanded into distinct standalone character-life situations'),
    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_bbcd384b699f.situation_2', semantic_group='character_life.topic_dresseshobbies_bbcd384b699f', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='旋律把难念的音节轻轻托起来，发音练习也没那么像功课。', source_kind='topic_rewrite', source_reference='legacy:72297;topic:topic_dresseshobbies_bbcd384b699f', rewrite_reason='expanded into distinct standalone character-life situations'),
