    CatalogEntry(category='DressesHobbies', category_group='character_life', variant_id='topic_dresseshobbies_bbcd384b699f.situation_4', semantic_group='character_life.topic_dresseshobbies_bbcd384b699f', output_mode='self_talk', trigger='idle', required_context='none', tone='soft_playful', interrupt_cost=0, cooldown_hours=144.0, semantic_cooldown_hours=96.0, max_per_day=1, weight=1.0, text='戴着耳机轻声跟唱时，我能为了一个尾音来回琢磨好久。', source_kind='topic_rewrite', source_reference='legacy:72299;topic:topic_dresseshobbies_bbcd384b699f', rewrite_reason='expanded into distinct standalone character-life situations'),
